1	//! Pure recovery-history replay. Verified claims are not a current output file,
2	//! durable mutation acknowledgment, standalone schema or writer activation.
3	use crate::{
4	    evidence::{self, Decoded},
5	    evidence_recovery_commitment::{
6	        self as commitment, Counts, Domain, Header, Limits, MemberFraming, RestorationFraming,
7	    },
8	    evidence_recovery_member::{self as member, Availability, Basis, Input, Member, Object},
9	    evidence_recovery_observation::{self as observation, Authenticated, Context},
10	};
11	use atproto_dasl::{Cid, Ipld};
12	use sha2::{Digest, Sha256};
13	use std::{
14	    collections::BTreeMap,
15	    sync::atomic::Ordering,
16	    time::{Duration, Instant},
17	};
18	type Result<T> = std::result::Result<T, Error>;
19	#[derive(Debug, thiserror::Error, PartialEq, Eq)]
20	pub enum Error {
21	    #[error("invalid recovery history: {0}")]
22	    Invalid(&'static str),
23	    #[error("recovery replay budget exhausted")]
24	    Budget,
25	    #[error("recovery replay cancelled")]
26	    Cancelled,
27	    #[error("invalid recovery member: {0}")]
28	    Member(#[from] member::Error),
29	}
30	fn require(ok: bool, reason: &'static str) -> Result<()> {
31	    if ok {
32	        Ok(())
33	    } else {
34	        Err(Error::Invalid(reason))
35	    }
36	}
37	fn member_error(e: member::Error) -> Error {
38	    match e {
39	        member::Error::Budget => Error::Budget,
40	        member::Error::Cancelled => Error::Cancelled,
41	        e => Error::Member(e),
42	    }
43	}
44	fn commitment_error(e: commitment::Error) -> Error {
45	    match e {
46	        commitment::Error::Budget => Error::Budget,
47	        commitment::Error::Cancelled => Error::Cancelled,
48	        _ => Error::Invalid("commitment framing"),
49	    }
50	}
51	/// Supply only from owner configuration retained independently of this bundle.
52	/// None at verify means no externally checkpointed rollback protection.
53	#[derive(Clone, Debug, PartialEq, Eq)]
54	pub struct Checkpoint {
55	    pub context: Context,
56	    pub sequence: u64,
57	    pub statement: Cid,
58	}
59	#[derive(Clone, Debug)]
60	pub struct Attempt {
61	    pub id: [u8; 16],
62	    pub intent: Cid,
63	    pub output: [u8; 32],
64	    pub restorations: [u8; 32],
65	    pub failure_count: u64,
66	    /// The observer's attributed claim; not proof of current physical output.
67	    pub observed_at_sequence: Option<u64>,
68	}
69	/// Verified candidate bytes, with source membership authority kept separate.
70	#[derive(Clone, Debug, PartialEq, Eq)]
71	pub struct Restoration {
72	    pub cid: Cid,
73	    pub length: u64,
74	    pub basis: Basis,
75	}
76	pub struct Replay {
77	    member: Member,
78	    checkpoint: Checkpoint,
79	    external: Option<Checkpoint>,
80	    restorations: Vec<Restoration>,
81	    attempts: Vec<Attempt>,
82	}
83	impl Replay {
84	    pub fn member(&self) -> &Member {
85	        &self.member
86	    }
87	    pub fn latest(&self) -> &Checkpoint {
88	        &self.checkpoint
89	    }
90	    pub fn external(&self) -> Option<&Checkpoint> {
91	        self.external.as_ref()
92	    }
93	    pub fn restored(&self) -> u64 {
94	        self.restorations.len() as u64
95	    }
96	    pub fn restorations(&self) -> &[Restoration] {
97	        &self.restorations
98	    }
99	    pub fn attempts(&self) -> &[Attempt] {
100	        &self.attempts
101	    }
102	}
103	struct Work {
104	    limits: Limits,
105	    deadline: Instant,
106	    items: u64,
107	    bytes: u64,
108	}
109	impl Work {
110	    fn new(limits: Limits) -> Result<Self> {
111	        require(
112	            !limits.duration.is_zero() && limits.duration <= Duration::from_secs(3600),
113	            "duration",
114	        )?;
115	        let deadline = Instant::now()
116	            .checked_add(limits.duration)
117	            .ok_or(Error::Budget)?;
118	        let s = Self {
119	            limits,
120	            deadline,
121	            items: 0,
122	            bytes: 0,
123	        };
124	        s.check()?;
125	        Ok(s)
126	    }
127	    fn check(&self) -> Result<()> {
128	        if self.limits.cancelled.load(Ordering::Relaxed) {
129	            return Err(Error::Cancelled);
130	        }
131	        if Instant::now() >= self.deadline {
132	            return Err(Error::Budget);
133	        }
134	        Ok(())
135	    }
136	    fn charge(&mut self, items: u64, bytes: u64) -> Result<()> {
137	        self.check()?;
138	        self.items = self.items.checked_add(items).ok_or(Error::Budget)?;
139	        self.bytes = self.bytes.checked_add(bytes).ok_or(Error::Budget)?;
140	        if self.items > self.limits.items || self.bytes > self.limits.bytes {
141	            return Err(Error::Budget);
142	        }
143	        Ok(())
144	    }
145	    fn remaining(&self) -> Result<Duration> {
146	        self.check()?;
147	        let d = self.deadline.saturating_duration_since(Instant::now());
148	        if d.is_zero() {
149	            Err(Error::Budget)
150	        } else {
151	            Ok(d)
152	        }
153	    }
154	    fn hash(&self, bytes: &[u8]) -> Result<[u8; 32]> {
155	        let mut h = Sha256::new();
156	        for part in bytes.chunks(65536) {
157	            self.check()?;
158	            h.update(part)
159	        }
160	        Ok(h.finalize().into())
161	    }
162	    fn framing_limits(&self, items: u64, input_bytes: u64) -> Result<Limits> {
163	        // Framing overhead is bounded by each local field/item ceiling. Scan
164	        // accounting counts encoded inputs; the framing layer counts hash work.
165	        let bytes = input_bytes
166	            .checked_mul(4)
167	            .and_then(|n| n.checked_add(items.checked_mul(128)?))
168	            .and_then(|n| n.checked_add(1024))
169	            .ok_or(Error::Budget)?;
170	        Ok(Limits {
171	            items,
172	            bytes,
173	            duration: self.remaining()?,
174	            cancelled: self.limits.cancelled.clone(),
175	        })
176	    }
177	}
178	fn map<const N: usize>(fields: [(&str, Ipld); N]) -> Ipld {
179	    Ipld::Map(fields.into_iter().map(|(k, v)| (k.into(), v)).collect())
180	}
181	fn fields(v: &Ipld) -> Result<&BTreeMap<String, Ipld>> {
182	    match v {
183	        Ipld::Map(m) => Ok(m),
184	        _ => Err(Error::Invalid("map")),
185	    }
186	}
187	fn bytes<const N: usize>(v: &Ipld) -> Result<[u8; N]> {
188	    match v {
189	        Ipld::Bytes(b) => b
190	            .as_slice()
191	            .try_into()
192	            .map_err(|_| Error::Invalid("byte width")),
193	        _ => Err(Error::Invalid("bytes")),
194	    }
195	}
196	fn link(v: &Ipld) -> Result<&Cid> {
197	    match v {
198	        Ipld::Link(c) => Ok(c),
199	        _ => Err(Error::Invalid("link")),
200	    }
201	}
202	fn integer(v: &Ipld) -> Result<u64> {
203	    evidence::uint(v)
204	        .map(|n| n as u64)
205	        .map_err(|_| Error::Invalid("integer"))
206	}
207	fn frontier(m: &Member) -> Ipld {
208	    let f = m.frontier();
209	    map([
210	        ("through", Ipld::Integer(f.through.into())),
211	        (
212	            "manifest",
213	            f.manifest.clone().map(Ipld::Link).unwrap_or(Ipld::Null),
214	        ),
215	        (
216	            "attestation",
217	            f.attestation.clone().map(Ipld::Link).unwrap_or(Ipld::Null),
218	        ),
219	    ])
220	}
221	fn loss(l: &member::Loss) -> Ipld {
222	    map([
223	        (
224	            "occurrence",
225	            l.occurrence
226	                .map(|n| Ipld::Integer(n.into()))
227	                .unwrap_or(Ipld::Null),
228	        ),
229	        ("cid", Ipld::Link(l.cid.clone())),
230	        (
231	            "expectedLength",
232	            l.expected_length
233	                .map(|n| Ipld::Integer(n.into()))
234	                .unwrap_or(Ipld::Null),
235	        ),
236	        (
237	            "state",
238	            Ipld::String(
239	                match l.state {
240	                    Availability::Missing => "missing",
241	                    Availability::Corrupt => "corrupt",
242	                    Availability::Available => unreachable!("member losses exclude available"),
243	                }
244	                .into(),
245	            ),
246	        ),
247	    ])
248	}
249	/// Charge acquisition-sized passes; does not acquire or duplicate payloads.
250	fn input_cost(input: Input<'_>, work: &mut Work) -> Result<(u64, u64)> {
251	    let n = input
252	        .records
253	        .len()
254	        .checked_add(input.membership.len())
255	        .and_then(|n| n.checked_add(input.objects.len()))
256	        .ok_or(Error::Budget)? as u64;
257	    work.charge(n, 0)?;
258	    let before = work.bytes;
259	    if let Some(p) = input.plan {
260	        work.charge(0, p.len() as u64)?
261	    }
262	    for r in input.records {
263	        for b in [r.manifest, r.receipt, r.proof] {
264	            work.charge(0, b.len() as u64)?
265	        }
266	    }
267	    for _ in input.membership {
268	        work.charge(0, 44)?
269	    }
270	    for o in input.objects {
271	        work.charge(0, o.bytes.len() as u64)?
272	    }
273	    Ok((n, work.bytes - before))
274	}
275	fn audit(input: Input<'_>, work: &mut Work) -> Result<Member> {
276	    let (items, size) = input_cost(input, work)?;
277	    // The member audit also computes M1 over the same input collection.
278	    work.charge(0, size)?;
279	    let m = member::verify(
280	        input,
281	        member::Budget {
282	            items,
283	            input_bytes: size,
284	            duration: work.remaining()?,
285	            cancelled: work.limits.cancelled.clone(),
286	        },
287	    )
288	    .map_err(member_error)?;
289	    work.check()?;
290	    Ok(m)
291	}
292	struct Key<'a> {
293	    cid: Cid,
294	    length: Option<u64>,
295	    original: Option<&'a [u8]>,
296	    basis: Basis,
297	}
298	fn keys<'a>(
299	    input: Input<'a>,
300	    complete_recipe: bool,
301	    work: &mut Work,
302	) -> Result<BTreeMap<String, Key<'a>>> {
303	    let mut out = BTreeMap::new();
304	    for m in input.membership {
305	        work.check()?;
306	        out.insert(
307	            m.cid.to_string(),
308	            Key {
309	                cid: m.cid.clone(),
310	                length: complete_recipe.then_some(m.length),
311	                original: None,
312	                basis: if complete_recipe {
313	                    Basis::VerifiedCopyRecipe
314	                } else {
315	                    Basis::UnverifiedMembership
316	                },
317	            },
318	        );
319	    }
320	    for row in input.records {
321	        work.charge(0, row.manifest.len() as u64)?;
322	        let Decoded::Known(record) =
323	            evidence::decode(row.manifest).map_err(|_| Error::Invalid("member changed"))?
324	        else {
325	            return Err(Error::Invalid("member changed"));
326	        };
327	        let Ipld::List(es) = &record.body()["entries"] else {
328	            return Err(Error::Invalid("member entries"));
329	        };
330	        let e = fields(es.first().ok_or(Error::Invalid("member entries"))?)?;
331	        let cid = link(&e["ciphertext"])?;
332	        let length = integer(&e["length"])?;
333	        out.entry(cid.to_string())
334	            .and_modify(|key| {
335	                key.length = Some(length);
336	                key.basis = Basis::IssuerMetadata;
337	            })
338	            .or_insert_with(|| Key {
339	                cid: cid.clone(),
340	                length: Some(length),
341	                original: None,
342	                basis: Basis::IssuerMetadata,
343	            });
344	    }
345	    for o in input.objects {
346	        work.check()?;
347	        out.entry(o.cid.to_string())
348	            .or_insert_with(|| Key {
349	                cid: o.cid.clone(),
350	                length: None,
351	                original: None,
352	                basis: Basis::OriginalObject,
353	            })
354	            .original = Some(o.bytes);
355	    }
356	    Ok(out)
357	}
358	fn expected_partition(auth: &Authenticated, losses: &[member::Loss]) -> Result<Vec<Ipld>> {
359	    let mut entries: Vec<_> = losses.iter().take(32).map(loss).collect();
360	    while !entries.is_empty() {
361	        let mut st = auth.statement().clone();
362	        let Ipld::Map(s) = &mut st else {
363	            unreachable!()
364	        };
365	        let Ipld::Map(body) = s.get_mut("body").expect("authenticated body") else {
366	            unreachable!()
367	        };
368	        body.insert("entries".into(), Ipld::List(entries.clone()));
369	        let raw = atproto_dasl::to_vec(&st).map_err(|_| Error::Invalid("partition encoding"))?;
370	        let envelope = atproto_dasl::to_vec(&map([
371	            ("statement", Ipld::Bytes(raw)),
372	            ("signature", Ipld::Bytes(vec![0; 64])),
373	        ]))
374	        .map_err(|_| Error::Invalid("partition encoding"))?;
375	        if envelope.len() <= observation::MAX_ENVELOPE {
376	            return Ok(entries);
377	        }
378	        entries.pop();
379	    }
380	    Err(Error::Invalid("unrepresentable loss"))
381	}
382	fn output_commitments<'a>(
383	    input: Input<'a>,
384	    original: &Member,
385	    keys: &BTreeMap<String, Key<'a>>,
386	    selected: &BTreeMap<String, &'a [u8]>,
387	    work: &mut Work,
388	) -> Result<([u8; 32], [u8; 32])> {
389	    require(
390	        original.recipe_metadata_complete(),
391	        "partial copy publication",
392	    )?;
393	    let mut selected_bytes = 0u64;
394	    for b in selected.values() {
395	        work.check()?;
396	        selected_bytes = selected_bytes
397	            .checked_add(b.len() as u64)
398	            .ok_or(Error::Budget)?
399	    }
400	    // R1 re-verifies candidates and hashes them into its commitment.
401	    work.charge(
402	        selected.len() as u64,
403	        selected_bytes.checked_mul(2).ok_or(Error::Budget)?,
404	    )?;
405	    let mut r = RestorationFraming::new(
406	        selected.len() as u64,
407	        work.framing_limits(selected.len() as u64, selected_bytes)?,
408	    )
409	    .map_err(commitment_error)?;
410	    for (k, b) in selected {
411	        r.candidate(&keys[k].cid, b).map_err(commitment_error)?
412	    }
413	    let r1 = r.finish().map_err(commitment_error)?;
414	    let mut objects = Vec::with_capacity(keys.len());
415	    for (name, k) in keys {
416	        work.check()?;
417	        let data = selected
418	            .get(name)
419	            .copied()
420	            .or(k.original)
421	            .ok_or(Error::Invalid("publication-blocked-unavailable-object"))?;
422	        objects.push(Object {
423	            cid: &k.cid,
424	            bytes: data,
425	        });
426	    }
427	    let virtual_input = Input {
428	        objects: &objects,
429	        ..input
430	    };
431	    let output = audit(virtual_input, work).map_err(|error| match error {
432	        Error::Member(_) => Error::Invalid("output member validation"),
433	        error => error,
434	    })?;
435	    require(
436	        output.losses().is_empty(),
437	        "publication-blocked-unavailable-object",
438	    )?;
439	    require(
440	        output.recipe_metadata_complete()
441	            && output.frontier() == original.frontier()
442	            && output.verified_requests() == original.frontier().through,
443	        "incomplete output",
444	    )?;
445	    let (items, size) = input_cost(virtual_input, work)?;
446	    let mut o = MemberFraming::new(
447	        Header {
448	            profile: input.context.profile,
449	            archive: input.context.archive,
450	            scope: input.context.scope,
451	            issuer: &input.context.issuer,
452	            plan: input.plan,
453	        },
454	        Counts {
455	            membership: input.membership.len() as u64,
456	            records: input.records.len() as u64,
457	            objects: objects.len() as u64,
458	        },
459	        Domain::Output,
460	        work.framing_limits(items, size)?,
461	    )
462	    .map_err(commitment_error)?;
463	    for m in input.membership {
464	        o.membership(m.cid, m.length).map_err(commitment_error)?
465	    }
466	    o.begin_records().map_err(commitment_error)?;
467	    for r in input.records {
468	        o.record(r.sequence, r.manifest, r.receipt, r.proof)
469	            .map_err(commitment_error)?
470	    }
471	    o.begin_objects().map_err(commitment_error)?;
472	    for b in objects {
473	        o.original_object(b.cid, b.bytes)
474	            .map_err(commitment_error)?
475	    }
476	    let o1 = o.finish().map_err(commitment_error)?;
477	    work.check()?;
478	    Ok((r1, o1))
479	}
