481	/// Verify all supplied history, not just through the owner's selected checkpoint.
482	/// bytes counts encoded-input scan passes as documented in the codec design.
483	pub fn verify<'a>(
484	    input: Input<'a>,
485	    candidates: &'a [Object<'a>],
486	    observations: &[&[u8]],
487	    external: Option<&Checkpoint>,
488	    limits: Limits,
489	) -> Result<Replay> {
490	    let mut work = Work::new(limits)?;
491	    require(!observations.is_empty(), "missing observation history")?;
492	    if let Some(p) = external {
493	        require(
494	            p.context == *input.context
495	                && p.sequence > 0
496	                && p.sequence <= evidence::MAX_SAFE_INTEGER as u64,
497	            "external checkpoint context",
498	        )?
499	    }
500	    // Reject an already-known oversized history before auditing payloads.
501	    work.charge(observations.len() as u64, 0)?;
502	    let original = audit(input, &mut work)?;
503	    let expected_frontier = frontier(&original);
504	    let keys = keys(input, original.recipe_metadata_complete(), &mut work)?;
505	    work.charge(candidates.len() as u64, 0)?;
506	    let mut physical = BTreeMap::new();
507	    let mut last: Option<String> = None;
508	    for c in candidates {
509	        work.charge(0, c.bytes.len() as u64)?;
510	        require(
511	            !c.bytes.is_empty() && c.bytes.len() <= 4 * 1024 * 1024,
512	            "candidate bounds",
513	        )?;
514	        let raw = c.cid.to_bytes();
515	        require(
516	            raw.len() == 36 && raw[..4] == [1, 0x55, 0x12, 0x20],
517	            "candidate CID",
518	        )?;
519	        let name = c.cid.to_string();
520	        require(
521	            last.as_ref().is_none_or(|old| old < &name),
522	            "candidate order or duplicate",
523	        )?;
524	        last = Some(name.clone());
525	        let target = keys
526	            .get(&name)
527	            .ok_or(Error::Invalid("candidate outside member"))?;
528	        require(
529	            target.length.is_none_or(|n| n == c.bytes.len() as u64),
530	            "candidate expected length",
531	        )?;
532	        require(work.hash(c.bytes)? == raw[4..], "candidate hash")?;
533	        physical.insert(name, c.bytes);
534	    }
535	    let mut previous: Option<Authenticated> = None;
536	    let mut loss_offset = 0;
537	    let mut selected = BTreeMap::new();
538	    let mut attempts = BTreeMap::<[u8; 16], Attempt>::new();
539	    let mut cached: Option<([u8; 32], [u8; 32])> = None;
540	    let mut checkpoint_seen = external.is_none();
541	    for raw in observations {
542	        work.charge(0, raw.len() as u64)?;
543	        let auth = observation::authenticate(raw, input.context, previous.as_ref())
544	            .map_err(|_| Error::Invalid("observation authentication"))?;
545	        let st = fields(auth.statement())?;
546	        let b = fields(&st["body"])?;
547	        let Ipld::String(event) = &st["event"] else {
548	            unreachable!()
549	        };
550	        if let Some(value) = b.get("member") {
551	            require(
552	                bytes::<32>(value)? == *original.commitment(),
553	                "member commitment",
554	            )?
555	        }
556	        if let Some(value) = b.get("frontier") {
557	            require(value == &expected_frontier, "metadata frontier")?
558	        }
559	        if auth.sequence() == 1 {
560	            require(event == "created", "created position")?
561	        } else if loss_offset < original.losses().len() {
562	            require(event == "unavailable", "initial loss incomplete")?;
563	            let expected = expected_partition(&auth, &original.losses()[loss_offset..])?;
564	            require(
565	                b["entries"] == Ipld::List(expected.clone()),
566	                "initial loss partition",
567	            )?;
568	            loss_offset += expected.len();
569	        } else {
570	            match event.as_str() {
571	                "unavailable" => return Err(Error::Invalid("late unavailable")),
572	                "restored" => {
573	                    let name = link(&b["cid"])?.to_string();
574	                    let data = physical
575	                        .get(&name)
576	                        .ok_or(Error::Invalid("restoration without candidate"))?;
577	                    require(
578	                        integer(&b["length"])? == data.len() as u64,
579	                        "restoration length",
580	                    )?;
581	                    require(!selected.contains_key(&name), "duplicate restoration")?;
582	                    selected.insert(name, *data);
583	                    cached = None;
584	                }
585	                "publication-intent" => {
586	                    let id = bytes::<16>(&b["attempt"])?;
587	                    require(!attempts.contains_key(&id), "duplicate intent")?;
588	                    let (r1, o1) = match cached {
589	                        Some(c) => c,
590	                        None => {
591	                            let c =
592	                                output_commitments(input, &original, &keys, &selected, &mut work)?;
593	                            cached = Some(c);
594	                            c
595	                        }
596	                    };
597	                    require(
598	                        bytes::<32>(&b["restorations"])? == r1,
599	                        "historical restorations",
600	                    )?;
601	                    require(bytes::<32>(&b["output"])? == o1, "intent output")?;
602	                    attempts.insert(
603	                        id,
604	                        Attempt {
605	                            id,
606	                            intent: auth.statement_cid().clone(),
607	                            output: o1,
608	                            restorations: r1,
609	                            failure_count: 0,
610	                            observed_at_sequence: None,
611	                        },
612	                    );
613	                }
614	                "publication-observed" | "publication-failed" => {
615	                    let id = bytes::<16>(&b["attempt"])?;
616	                    let a = attempts
617	                        .get_mut(&id)
618	                        .ok_or(Error::Invalid("unknown attempt"))?;
619	                    require(link(&b["intent"])? == &a.intent, "intent citation")?;
620	                    require(a.observed_at_sequence.is_none(), "event after observed")?;
621	                    if event == "publication-observed" {
622	                        require(bytes::<32>(&b["output"])? == a.output, "observed output")?;
623	                        a.observed_at_sequence = Some(auth.sequence());
624	                    } else {
625	                        a.failure_count = a.failure_count.checked_add(1).ok_or(Error::Budget)?
626	                    }
627	                }
628	                _ => return Err(Error::Invalid("event position")),
629	            }
630	        }
631	        if let Some(pin) = external {
632	            if pin.sequence == auth.sequence() {
633	                require(
634	                    &pin.statement == auth.statement_cid(),
635	                    "external checkpoint statement",
636	                )?;
637	                checkpoint_seen = true
638	            }
639	        }
640	        previous = Some(auth);
641	        work.check()?;
642	    }
643	    require(
644	        loss_offset == original.losses().len(),
645	        "initial loss incomplete",
646	    )?;
647	    require(
648	        selected.len() == physical.len(),
649	        "candidate without restoration",
650	    )?;
651	    require(checkpoint_seen, "external checkpoint absent")?;
652	    let tip = previous.expect("nonempty verified history");
653	    work.check()?;
654	    Ok(Replay {
655	        member: original,
656	        checkpoint: Checkpoint {
657	            context: input.context.clone(),
658	            sequence: tip.sequence(),
659	            statement: tip.statement_cid().clone(),
660	        },
661	        external: external.cloned(),
662	        restorations: selected
663	            .iter()
664	            .map(|(name, data)| Restoration {
665	                cid: keys[name].cid.clone(),
666	                length: data.len() as u64,
